-- Safe onboarding progress: plaintext recovery material is never stored.
alter table public.profiles add column if not exists recovery_acknowledged_at timestamptz, add column if not exists profile_completed_at timestamptz, add column if not exists country_handled_at timestamptz, add column if not exists interests_handled_at timestamptz;
create or replace function public.complete_onboarding() returns boolean language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); country text; begin perform require_authenticated(); select country_code into country from profiles where id=uid and recovery_acknowledged_at is not null and profile_completed_at is not null and country_handled_at is not null and interests_handled_at is not null; if not found then raise exception 'Onboarding steps are incomplete'; end if; if not exists(select 1 from room_members m join rooms r on r.id=m.room_id where m.user_id=uid and r.kind='world') then raise exception 'World membership is required'; end if; if country is not null and country <> 'XX' and not exists(select 1 from room_members m join rooms r on r.id=m.room_id where m.user_id=uid and r.slug='country-'||lower(country)) then raise exception 'Country membership is required'; end if; update profiles set onboarding_completed=true where id=uid; return true; end $$;
revoke all on function public.complete_onboarding() from public; grant execute on function public.complete_onboarding() to authenticated;
